describe('Table Loading State', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display loading state while data is fetching', () => {
    // Intercept the API call to simulate loading
    cy.intercept('GET', '/api/table/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: {
            data: [
              { id: 1, name: 'Item 1', status: 'active' },
              { id: 2, name: 'Item 2', status: 'inactive' },
            ],
          },
        });
      });
    }).as('fetchTableData');

    // Verify loading indicator is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Loading data...');

    // Verify table rows are not yet visible
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Wait for the API call to complete
    cy.wait('@fetchTableData');

    // Verify loading indicator is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="loading-text"]').should('not.exist');

    // Verify table rows are now visible
    cy.get('[data-testid="table-row"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length', 2);

    // Verify data is displayed correctly
    cy.get('[data-testid="table-row"]').first().should('contain', 'Item 1');
    cy.get('[data-testid="table-row"]').first().should('contain', 'active');
  });

  it('should handle API error and display error message', () => {
    // Intercept the API call to simulate an error
    cy.intercept('GET', '/api/table/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' },
    }).as('fetchTableDataError');

    // Verify loading indicator is visible initially
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for the failed API call
    cy.wait('@fetchTableDataError');

    // Verify loading indicator is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify table is not displayed
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');

    // Verify error state persists
    cy.get('[data-testid="error-message"]').should('be.visible');
  });
});
